def mime_image(o):
    if o[:4] == b"\x89PNG":
        return "image/png"
    if o[:3] == b"GIF":
        return "image/gif"
    if o[:4] == b"RIFF" and o[8:12] == b"WEBP":
        return "image/webp"
    return "image/jpeg"


def charger_fond():
    """Retourne le logo en data-URI (couleurs d'origine, format réel détecté à partir du contenu)."""
