# ---------- Source : site web (6 étapes : entrée, sécurité, exploration, graphe, calcul, affichage) ----------
ROBOT = "AnalyseurCentralite"
EXT_IGNOREES = (".pdf", ".jpg", ".jpeg", ".png", ".gif", ".webp", ".svg", ".zip", ".rar", ".mp3", ".mp4",
                ".avi", ".doc", ".docx", ".xls", ".xlsx", ".ppt", ".pptx", ".css", ".js", ".ico", ".xml")
SOCIAUX = {"facebook.com": "Facebook", "fb.com": "Facebook", "youtube.com": "YouTube", "youtu.be": "YouTube",
           "tiktok.com": "TikTok", "instagram.com": "Instagram", "twitter.com": "X", "x.com": "X",
           "linkedin.com": "LinkedIn", "snapchat.com": "Snapchat", "t.me": "Telegram", "github.com": "GitHub"}


def url_sure(url):
    """Étape 2 : refuse les adresses locales, privées ou inaccessibles."""
    p = urllib.parse.urlparse(url)
    if p.scheme not in ("http", "https") or not p.hostname:
        return False
    try:
        return all(ipaddress.ip_address(i[4][0]).is_global
                   for i in socket.getaddrinfo(p.hostname, None))
    except (socket.gaierror, ValueError):
        return False


def entree_url(texte):
    """Étape 1 : « exemple.com » devient « https://exemple.com »."""
    t = texte.strip()
    return t if "://" in t else "https://" + t


def propre(u):
    """Adresse sans fragment ni paramètres, sans « / » final : une page = un nœud."""
    p = urllib.parse.urlparse(u)
    return urllib.parse.urlunparse((p.scheme.lower(), p.netloc.lower(), p.path.rstrip("/"), "", "", ""))


def domaine_de(u):
    h = urllib.parse.urlparse(u).netloc.lower()
    return h[4:] if h.startswith("www.") else h


def reseau_social(domaine):
    return next((nom for d, nom in SOCIAUX.items() if domaine == d or domaine.endswith("." + d)), None)


def telecharger(url):
    """Télécharge une page HTML en vérifiant la sécurité à chaque redirection ; (adresse finale, html) ou None."""
    for _ in range(4):
        if not url_sure(url):
            return None
        try:
            r = requests.get(url, timeout=6, headers={"User-Agent": ROBOT}, allow_redirects=False, stream=True)
            if r.status_code in (301, 302, 303, 307, 308) and r.headers.get("Location"):
                url = urllib.parse.urljoin(url, r.headers["Location"])
                r.close()
                continue
            if r.status_code != 200 or "text/html" not in r.headers.get("Content-Type", ""):
                r.close()
                return None
            contenu = r.raw.read(1_500_000, decode_content=True)
            enc = r.encoding or "utf-8"
            r.close()
            return url, contenu.decode(enc, "replace")
        except requests.RequestException:
            return None
    return None


def depuis_site(url, max_pages):
    """Étapes 3 et 4 : explore le site en largeur depuis l'accueil et construit le graphe des liens internes."""
    url = propre(url)
    domaine = domaine_de(url)
    robots = urllib.robotparser.RobotFileParser()
    try:
        r = requests.get(urllib.parse.urljoin(url, "/robots.txt"), timeout=5, headers={"User-Agent": ROBOT})
        robots.parse(r.text.splitlines() if r.status_code == 200 else [])
    except requests.RequestException:
        robots.parse([])
    file, vues, G = deque([url]), set(), nx.DiGraph()
    titres, sociaux, externes, interdites, redirections = {}, {}, 0, 0, {}
    while file and len(vues) < max_pages:
        page = file.popleft()
        if page in vues:
            continue
        if not robots.can_fetch(ROBOT, page):      # respect du robots.txt du site
            interdites += 1
            continue
        vues.add(page)
        rep = telecharger(page)
        if not rep or domaine_de(rep[0]) != domaine:
            continue
        final, html = rep
        if propre(final) != page:                    # redirection : la page devient celle de destination
            redirections[page] = propre(final)
            if propre(final) not in vues and propre(final) not in file:
                file.append(propre(final))
            continue
        soupe = BeautifulSoup(html, "html.parser")
        titres[page] = soupe.title.get_text(" ", strip=True) if soupe.title else ""
        G.add_node(page)
        for a in soupe.find_all("a", href=True):
            href = a["href"].strip()
            if href.lower().startswith(("mailto:", "tel:", "javascript:", "#")):
                continue
            cible = urllib.parse.urljoin(final, href)
            if not cible.startswith(("http://", "https://")):
                continue
            if domaine_de(cible) == domaine:
                cible = propre(cible)
                if cible == page or cible.lower().endswith(EXT_IGNOREES):
                    continue
                G.add_edge(page, cible)
                if cible not in vues and cible not in file:
                    file.append(cible)
            else:
                externes += 1
                nom = reseau_social(domaine_de(cible))
                if nom:
                    sociaux[nom] = sociaux.get(nom, 0) + 1
        time.sleep(0.2)                              # politesse envers le serveur
    G = nx.relabel_nodes(G, redirections)            # fusionne les pages redirigées avec leur destination
    G.remove_edges_from(list(nx.selfloop_edges(G)))
    for u, t in titres.items():
        if u in G and t:
            G.nodes[u]["nom"] = t
    morceaux = ["%d page(s) explorée(s) sur %d découverte(s)" % (len(titres), G.number_of_nodes()),
                "%d lien(s) interne(s)" % G.number_of_edges(), "%d lien(s) externe(s)" % externes]
    if sociaux:
        morceaux.append("liens vers " + ", ".join("%s (%d)" % kv for kv in sorted(sociaux.items())))
    if interdites:
        morceaux.append("%d page(s) interdite(s) par robots.txt" % interdites)
    G.graph["resume"] = domaine + " : " + " · ".join(morceaux)
    return G


# ---------- Source : fichiers exportés (Facebook, Instagram, LinkedIn, Snapchat, X, YouTube, e-mail...) ----------
CLES_NOMS = ("name", "value", "Display Name", "Username", "Channel Title", "accountId")


def corriger(texte):
    """Les exports Facebook encodent mal les accents : on les répare."""
    try:
        return texte.encode("latin-1").decode("utf-8")
    except (UnicodeEncodeError, UnicodeDecodeError):
        return texte


def graphe_compte(obj, centre, cls):
    """Export personnel (JSON) : relie le propriétaire du compte à chaque contact trouvé."""
    noms = set()

    def parcourir(o):
        if isinstance(o, dict):
            for cle in CLES_NOMS:
                if isinstance(o.get(cle), str) and o[cle].strip():
                    noms.add(corriger(o[cle]).strip())
                    break
            for v in o.values():
                parcourir(v)
        elif isinstance(o, list):
            for v in o:
                parcourir(v)

    parcourir(obj)
    G = cls()
    G.add_edges_from((centre, n) for n in noms if n != centre)
    return G


def sans_accent(t):
    return "".join(c for c in unicodedata.normalize("NFKD", str(t)) if not unicodedata.combining(c))


def cle_nom(n):
    """Clé de comparaison : « Aina », « aina » et « AÏNA  » désignent la même personne."""
    return re.sub(r"[^\w@.\-]+", " ", sans_accent(n).casefold()).strip()


def propre_cellule(c):
    if c is None:
        return ""
    if isinstance(c, float) and c.is_integer():
        c = int(c)
    c = re.sub(r"[\u200b\ufeff]", "", str(c).replace("\r\n", "\n").replace("\r", "\n"))
    return "\n".join(re.sub(r"[^\S\n]+", " ", ligne).strip() for ligne in c.split("\n")).strip()


def unifier_noms(G):
    """Fusionne les graphies d'une même personne (majuscules, accents, espaces) ; affiche la plus soignée."""
    cle, variantes = {}, {}
    for n in G:
        aff = str(G.nodes[n].get("nom") or n).strip()
        cle[n] = cle_nom(n) or str(n)
        v = variantes.setdefault(cle[n], {})
        v[aff] = v.get(aff, 0) + 1
    H = nx.relabel_nodes(G, cle, copy=True)
    H.remove_edges_from(list(nx.selfloop_edges(H)))
    for k, v in variantes.items():
        meilleur = max(v, key=lambda a: (a != a.lower() and a != a.upper(), v[a]))
        if len(v) > 1 and meilleur in (meilleur.lower(), meilleur.upper()):   # seulement « rado » et « RADO » : on met « Rado »
            meilleur = meilleur.title()
        H.nodes[k]["nom"] = meilleur
    return H


# intitulés de colonnes reconnus (sans tenir compte des accents, majuscules, pluriels « (s) »)
DE = {"source", "acteur", "from", "de", "expediteur", "utilisateur", "origine", "depart", "debut",
      "personne 1", "personne a", "ami 1", "nom 1", "membre 1"}
VERS = {"cible", "target", "to", "vers", "destinataire", "destination", "arrivee", "fin",
        "personne 2", "personne b", "ami 2", "nom 2", "membre 2"}
AMIS = {"ami", "amis", "contact", "contacts", "relation", "relations", "connaissance", "connaissances", "friend",
        "friends", "follower", "followers", "following", "abonne", "abonnes", "suivi", "suivis", "voisins",
        "collegues", "lien", "liens", "amis facebook", "personnes connues"}
PRENOM = {"prenom", "prenoms", "first name", "firstname", "given name"}
FAMILLE = {"last name", "lastname", "family name", "surname", "nom de famille"}
NOM = {"nom", "noms", "name", "names", "nom complet", "full name", "fullname", "display name", "pseudo",
       "username", "identifiant", "channel title", "titre", "profil", "compte", "page", "personne", "membre",
       "etudiant", "eleve", "nom et prenom", "nom et prenoms", "noms et prenoms", "nom prenom", "nom prenoms",
       "prenom nom"}


def role(titre):
    k = cle_nom(re.sub(r"\(s\)", "", str(titre)))
    for nom, mots in (("de", DE), ("vers", VERS), ("amis", AMIS), ("prenom", PRENOM), ("famille", FAMILLE), ("nom", NOM)):
        if k in mots:
            return nom
    if k.startswith(("nom ", "name ")):
        return "nom"
    if k.startswith(("amis ", "contacts ")):
        return "amis"
    return None


def matrice(lignes, cls):
    """Matrice d'adjacence : mêmes noms en ligne et en colonne, une marque (1, x, oui...) = un lien."""
    for h in range(min(len(lignes), 15)):
        tete, corps = lignes[h][1:], lignes[h + 1:]
        while tete and not tete[-1]:
            tete.pop()
        if len(tete) >= 3 and len(corps) == len(tete) and [cle_nom(l[0]) for l in corps] == [cle_nom(c) for c in tete]:
            G = cls()
            for i, l in enumerate(corps):
                for j, v in enumerate(l[1:len(tete) + 1]):
                    if i != j and cle_nom(v) not in ("", "0", "non", "no", "false", "faux", "none"):
                        G.add_edge(l[0], tete[j])
            return G
    return None


def graphe_tableau(lignes, proprio, cls):
    """Feuille Excel ou CSV : matrice, liste de liens, tableau « Nom / Amis » ou liste de contacts (étoile)."""
    lignes = [[propre_cellule(c) for c in l] for l in lignes]
    lignes = [l for l in lignes if any(l)]
    if not lignes:
        return cls()
    largeur = max(len(l) for l in lignes)
    lignes = [l + [""] * (largeur - len(l)) for l in lignes]
    G = matrice(lignes, cls)
    if G is not None:
        return G
    G = cls()
    h = next((i for i, l in enumerate(lignes[:15]) if any(role(c) for c in l)), None)   # titres parfois sous un en-tête
    col = {}
    for i, c in enumerate(lignes[h] if h is not None else []):
        if role(c):
            col.setdefault(role(c), []).append(i)
    donnees = lignes[h + 1:] if h is not None else lignes

    def nom_de(l):
        pre = " ".join(l[i] for i in col.get("prenom", []) if l[i])
        fam = " ".join(l[i] for i in col.get("nom", []) + col.get("famille", []) if l[i])
        return (pre + " " + fam).strip()

    def lier(a, b):
        if a and b and cle_nom(a) != cle_nom(b):
            G.add_edge(a, b)

    if "de" in col and "vers" in col:
        for l in donnees:
            lier(l[col["de"][0]], l[col["vers"][0]])
    elif "amis" in col:
        for l in donnees:
            proprietaire = nom_de(l) or proprio
            for i in col["amis"]:
                for ami in re.split(r"[;,/|\n]+|\s+et\s+", l[i]):
                    lier(proprietaire, ami.strip())
    elif col.get("nom") or col.get("prenom") or col.get("famille"):
        for l in donnees:
            lier(proprio, nom_de(l))
    else:                                       # aucun titre reconnu : deux colonnes = liens, une seule = contacts
        textes = [i for i in range(largeur) if sum(1 for l in lignes if l[i]) >= max(2, len(lignes) // 2)]
        for l in lignes:
            if len(textes) >= 2:
                lier(l[textes[0]], l[textes[1]])
            elif textes:
                lier(proprio, l[textes[0]])
    return G


def graphe_excel(octets, centre, cls):
    """Classeur Excel (.xlsx). Plusieurs feuilles = plusieurs réseaux fusionnés ; le nom de la feuille est alors le propriétaire."""
    try:
        from openpyxl import load_workbook
    except ImportError:
        raise ValueError("lecture Excel impossible : installez openpyxl (pip install openpyxl)")
    wb = load_workbook(io.BytesIO(octets), read_only=True, data_only=True)
    G = cls()
    for ws in wb.worksheets:
        proprio = ws.title if len(wb.worksheets) > 1 else centre
        G = nx.compose(G, graphe_tableau(list(ws.iter_rows(values_only=True)), proprio, cls))
    return G


def graphe_courriels(octets, ext, cls):
    """Boîte mail exportée (.mbox ou .eml) : lien expéditeur -> destinataires."""
    messages = [octets] if ext == "eml" else re.split(rb"(?m)^From .*\r?\n", octets)
    analyseur = BytesParser(policy=policy.default)
    G = cls()
    for brut in messages:
        if not brut.strip():
            continue
        msg = analyseur.parsebytes(brut, headersonly=True)
        exp = getaddresses([str(msg.get("From", ""))])
        dest = getaddresses([str(h) for h in (msg.get_all("To", []) + msg.get_all("Cc", []))])
        if len(dest) > 20:  # courriers de masse ignorés
            continue
        for nom1, a1 in exp:
            for nom2, a2 in dest:
                a1, a2 = a1.lower(), a2.lower()
                if a1 and a2 and a1 != a2:
                    G.add_edge(a1, a2)
                    for a, nom in ((a1, nom1), (a2, nom2)):
                        if nom and nom.lower() != a and not G.nodes[a].get("nom"):
                            G.nodes[a]["nom"] = nom
    return G


def lire_fichier(nom, octets, cls):
    if nom.lower().endswith(".gz"):
        octets, nom = gzip.decompress(octets), nom[:-3]
    stem, _, ext = nom.rpartition(".")
    ext = ext.lower()
    centre = "Moi" if stem.lower() in GENERIQUES else stem
    if ext in ("mbox", "eml"):
        return graphe_courriels(octets, ext, cls)
    if ext == "json":
        return graphe_compte(json.loads(octets), centre, cls)
    if ext == "js":  # archive X : « window.YTD.following.part0 = [ ... ] »
        corps = octets.decode("utf-8", "ignore")
        return graphe_compte(json.loads(corps[corps.index("=") + 1:]), centre, cls)
    if ext == "xlsx":
        return graphe_excel(octets, centre, cls)
    if ext == "xls":
        raise ValueError("ancien format .xls non pris en charge : enregistrez le fichier au format .xlsx")
    if ext == "graphml":
        return cls(nx.read_graphml(io.BytesIO(octets)))
    if ext == "gexf":
        return cls(nx.read_gexf(io.BytesIO(octets)))
    texte = octets.decode("utf-8-sig", "ignore")
    if ext == "csv":      # séparateur « ; » des Excel français ou « , »
        sep = ";" if texte.count(";") > texte.count(",") else ","
        return graphe_tableau(list(csv.reader(io.StringIO(texte), delimiter=sep)), centre, cls)
    lignes = texte.replace(",", " ").replace(";", " ").splitlines()
    if lignes and lignes[0].lower().startswith(("source", "from", "id")):
        lignes = lignes[1:]
    return nx.parse_edgelist(lignes, comments="#", data=False, create_using=cls())


def depuis_fichiers(fichiers, oriente):
    cls = nx.DiGraph if oriente else nx.Graph
    G = cls()
    for f in fichiers:
        if f.filename:
            G = nx.compose(G, lire_fichier(f.filename, f.read(), cls))
    return unifier_noms(G)


# ---------- Sources : réseaux sociaux (plusieurs moyens par réseau) ----------
OUVERT = "Accès ouverts (les plus faciles)"
CONTRAINT = "Plus contraignants (clé ou jeton)"
FICHIER = "Sans accès public (fichier exporté)"


def get_json(url, headers=None, **kw):
    r = requests.get(url, timeout=15, headers={**UA, **(headers or {})}, **kw)
    if r.status_code in (401, 403, 429):
        raise ValueError("accès refusé ou limite atteinte (%d) : réseau protégé, jeton requis ou trop de requêtes" % r.status_code)
    r.raise_for_status()
    return r.json()


def entete_jeton(jeton):
    return {"Authorization": "Bearer " + jeton} if jeton else {}


def suivis(compte, pages=1, sens="suivis"):
    """Bluesky : (handle, nom) des comptes suivis ou des abonnés d'un compte public."""
    route, cle = ("getFollows", "follows") if sens == "suivis" else ("getFollowers", "followers")
    contacts, curseur = [], None
    for _ in range(pages):
        params = {"actor": compte, "limit": 100}
        if curseur:
            params["cursor"] = curseur
        r = requests.get(BSKY % route, params=params, timeout=15)
        r.raise_for_status()
        data = r.json()
        contacts += [(f["handle"], f.get("displayName") or "") for f in data.get(cle, [])]
        curseur = data.get("cursor")
        if not curseur:
            break
    return contacts


def v_bluesky(h, jeton, sens="suivis"):
    return suivis(h, pages=3, sens=sens)


def v_github(u, jeton, sens="suivis"):
    route = "following" if sens == "suivis" else "followers"
    d = get_json("https://api.github.com/users/%s/%s" % (u, route), entete_jeton(jeton), params={"per_page": 100})
    return [(x["login"], "") for x in d]


def v_mastodon(acct, jeton, sens="suivis"):
    user, _, inst = acct.lstrip("@").partition("@")
    inst = inst or "mastodon.social"
    base = "https://%s/api/v1/" % inst
    if not url_sure(base):
        raise ValueError("serveur Mastodon invalide")
    h = entete_jeton(jeton)
    i = get_json(base + "accounts/lookup", h, params={"acct": user})["id"]
    route = "following" if sens == "suivis" else "followers"
    d = get_json(base + "accounts/%s/%s" % (i, route), h, params={"limit": 80})
    return [(a["acct"] if "@" in a["acct"] else a["acct"] + "@" + inst, a.get("display_name", "")) for a in d]


def v_reddit(u, jeton, sens="suivis"):
    d = get_json("https://www.reddit.com/user/%s/comments.json" % u, params={"limit": 100})
    auteurs = {c["data"].get("link_author") for c in d["data"]["children"]}
    return [(a, "") for a in auteurs if a and a not in ("[deleted]", u)]


def v_wikipedia(titre, jeton, sens="suivis"):
    """Articles liés par la page (suivis) ou pages qui pointent vers elle (abonnés)."""
    prop, lim, ns = ("links", "pllimit", "plnamespace") if sens == "suivis" else ("linkshere", "lhlimit", "lhnamespace")
    d = get_json("https://fr.wikipedia.org/w/api.php", params={
        "action": "query", "titles": titre, "prop": prop, lim: "max", ns: 0, "format": "json"})
    return [(l["title"], l["title"]) for p in d["query"]["pages"].values() for l in p.get(prop, [])]


def v_x(u, jeton, sens="suivis"):
    if not jeton:
        raise ValueError("X exige un jeton d'accès (API payante) : renseignez le champ « jeton », "
                         "ou importez votre archive X (following.js) avec « Vos fichiers »")
    h = entete_jeton(jeton)
    i = get_json("https://api.x.com/2/users/by/username/%s" % u, h)["data"]["id"]
    route = "following" if sens == "suivis" else "followers"
    d = get_json("https://api.x.com/2/users/%s/%s" % (i, route), h, params={"max_results": 100})
    return [(a["username"], a.get("name", "")) for a in d.get("data", [])]


def cercle(voisins, compte, taille, jeton, sens="suivis"):
    """Réseau des contacts publics d'un compte : qui est lié à qui parmi eux."""
    contacts = dict(voisins(compte, jeton, sens)[:taille])
    if not contacts:
        raise ValueError("aucun contact public trouvé pour ce compte")

    def liens(n):
        try:
            return [(n, c) for c, _ in voisins(n, jeton, "suivis") if c in contacts and c != n]
        except (requests.RequestException, ValueError, KeyError):
            return []

    G = nx.DiGraph()
    with ThreadPoolExecutor(4) as pool:
        for aretes in pool.map(liens, contacts):
            G.add_edges_from(aretes)
    for n in G:
        G.nodes[n]["nom"] = contacts.get(n, "")
    return G


def depuis_reddit(compte, jeton, taille, sens="suivis"):
    """Deux moyens : un utilisateur (auteurs qu'il commente) ou un forum « r/nom » (qui répond à qui)."""
    if compte.lower().startswith("r/"):
        d = get_json("https://www.reddit.com/%s/comments.json" % compte, params={"limit": 100})
        G = nx.DiGraph()
        for c in d["data"]["children"]:
            a, b = c["data"].get("author"), c["data"].get("link_author")
            if a and b and a != b and "[deleted]" not in (a, b):
                G.add_edge(a, b)
        return G
    return cercle(v_reddit, compte, taille, jeton, sens)


CHAMPS_YT = ("items(snippet/topLevelComment/snippet(authorDisplayName,authorChannelId/value),"
             "replies/comments/snippet(authorDisplayName,authorChannelId/value))")  # jamais le texte


def depuis_youtube(ref, jeton, taille=0, sens="suivis"):
    """Réseau des commentateurs publics des 10 dernières vidéos d'une chaîne (API officielle)."""
    if not jeton:
        raise ValueError("clé API YouTube requise : collez-la dans le champ « jeton », ou écrivez-la dans "
                         "jetons.json ({\"youtube\": \"VOTRE_CLE\"}), ou importez subscriptions.csv (Google Takeout) avec « Vos fichiers »")
    yt = lambda route, **p: get_json("https://www.googleapis.com/youtube/v3/" + route, params={**p, "key": jeton})
    p = [x for x in urllib.parse.urlparse(ref if "//" in ref else "//" + ref).path.split("/") if x]
    ref = next((x for x in p if x.startswith("@")), None) or (p[1] if len(p) > 1 and p[0] == "channel" else (p[0] if p else ""))
    if not ref.startswith(("@", "UC")):
        ref = "@" + ref
    d = yt("channels", part="snippet,contentDetails", **({"forHandle": ref} if ref[0] == "@" else {"id": ref}))
    if not d.get("items"):
        raise ValueError("chaîne YouTube introuvable")
    ch = d["items"][0]
    cid, noms, G = ch["id"], {ch["id"]: ch["snippet"]["title"]}, nx.Graph()
    pl = ch["contentDetails"]["relatedPlaylists"]["uploads"]
    videos = yt("playlistItems", part="contentDetails", playlistId=pl, maxResults=10)["items"]

    def auteur(sn):
        a = (sn.get("authorChannelId") or {}).get("value")
        if a:
            noms[a] = sn.get("authorDisplayName", a)
        return a

    for v in videos:
        try:
            d = yt("commentThreads", part="snippet,replies", videoId=v["contentDetails"]["videoId"],
                   maxResults=100, fields=CHAMPS_YT)
        except ValueError:      # commentaires fermés
            continue
        for it in d.get("items", []):
            h = auteur(it["snippet"]["topLevelComment"]["snippet"])
            if not h:
                continue
            if h != cid:
                G.add_edge(cid, h)
            for c in it.get("replies", {}).get("comments", []):
                r = auteur(c["snippet"])
                if r and r != h:
                    G.add_edge(h, r)
    for n in G:
        G.nodes[n]["nom"] = noms.get(n, n)
    return G


# clé : (libellé, groupe, type, fonction, exemple)  ; type None = pas d'accès public
RESEAUX = {
    "bluesky": ("Bluesky", OUVERT, "cercle", v_bluesky, "handle ou lien du profil"),
    "mastodon": ("Mastodon", OUVERT, "cercle", v_mastodon, "nom@mastodon.social ou lien"),
    "github": ("GitHub", OUVERT, "cercle", v_github, "handle ou lien du profil"),
    "reddit": ("Reddit", OUVERT, "direct", depuis_reddit, "handle, lien, ou r/forum"),
    "wikipedia": ("Wikipédia (liens entre articles)", OUVERT, "cercle", v_wikipedia, "titre ou lien de l'article"),
    "youtube": ("YouTube", CONTRAINT, "direct", depuis_youtube, "@pseudo ou lien de la chaîne"),
    "x": ("X (Twitter)", CONTRAINT, "cercle", v_x, "handle ou lien du profil"),
    "linkedin": ("LinkedIn", FICHIER, None, None, "utilisez « Vos fichiers » en bas (Connections.csv)"),
    "snapchat": ("Snapchat", FICHIER, None, None, "utilisez « Vos fichiers » en bas"),
}


def groupes():
    g = {}
    for k, r in RESEAUX.items():
        g.setdefault(r[1], []).append((k, r))
    return g


def extraire(cle, texte):
    """Accepte un handle ou un lien (URL) et retourne l'identifiant propre au réseau."""
    t = texte.strip()
    if "://" not in t and "/" not in t:
        return t.lstrip("@")
    if cle == "reddit" and t.lower().startswith("r/"):
        return t
    u = urllib.parse.urlparse(t if "://" in t else "//" + t)
    seg = [s for s in u.path.split("/") if s]
    if cle == "mastodon":
        pseudo = next((s for s in seg if s.startswith("@")), "")
        return pseudo.lstrip("@") + "@" + u.netloc if pseudo else t
    if cle == "wikipedia":
        return urllib.parse.unquote(seg[-1]).replace("_", " ") if seg else t
    if cle == "reddit" and "r" in seg[:-1]:
        return "r/" + seg[seg.index("r") + 1]
    if cle == "youtube":
        return t            # depuis_youtube lit lui-même @pseudo, /channel/UC… ou le lien
    return seg[-1].lstrip("@") if seg else t


def depuis_reseau(cle, compte, jeton, sens):
    if cle not in RESEAUX:
        raise ValueError("clic ici pour choisir un réseau dans la liste")
    nom, _, type_, fn, _ = RESEAUX[cle]
    if type_ is None:
        raise ValueError("%s n'offre pas d'accès public : importez l'export de votre compte avec le formulaire « Vos fichiers » (en bas)" % nom)
    if not compte.strip():
        raise ValueError("indiquez un handle, une page ou un lien (ou joignez un fichier exporté)")
    compte, jeton = extraire(cle, compte), jeton_pour(cle, jeton)
    if type_ == "direct":
        return fn(compte, jeton, TAILLE, sens)
    return cercle(fn, compte, TAILLE, jeton, sens)


# ---------- Analyse et graphes ----------
def etiq(n):
    if isinstance(n, str) and n.startswith("http"):
        p = urllib.parse.urlparse(n)
        return p.path if p.path not in ("", "/") else "Accueil"
    return str(n)


def prenom(n):
    """Étiquette courte d'un nœud : prénom, ou début d'un identifiant."""
    t = etiq(n).strip()
    if isinstance(n, str) and n.startswith("http"):
        return t[:18]
    if "@" in t and " " not in t:
        local = t.split("@")[0]
        return (re.split(r"[._\-+0-9]+", local)[0] or local).capitalize()[:18]
    if " " in t:
        return t.split()[0]
    if "." in t and not t.replace(".", "").isdigit():
        return t.split(".")[0]
    return t[:18]


def libelle(G, n):
    """Nom affiché : celui écrit par la personne à l'inscription, sinon l'identifiant."""
    nom = str(G.nodes[n].get("nom", "")).strip()
    return nom or etiq(n)


def prenom_de(G, n):
    """Premier mot du nom affiché (sans emojis ni symboles), sinon début de l'identifiant."""
    brut = str(G.nodes[n].get("nom", ""))
    if isinstance(n, str) and n.startswith("http"):
        titre = re.split(r"\s[-–—|·•:]\s", brut)[0].strip()
        return titre[:22] or prenom(n)
    nom = "".join(c for c in brut if c.isalnum() or c in " -'.")
    mots = [m.strip("-'.") for m in nom.split()]
    return mots[0] if mots and mots[0] else prenom(n)


def en_png(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format="png", dpi=110, bbox_inches="tight")
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode()


def dessiner(G, deg, inter):
    n = G.number_of_nodes()
    if n > 150:
        top = sorted(G, key=lambda x: inter[x] + deg[x], reverse=True)[:80]
        H, titre = G.subgraph(top), "80 nœuds les plus centraux (sur %d)" % n
    else:
        H, titre = G, "Graphe complet"
    fig, ax = plt.subplots(figsize=(10, 8))
    pos = nx.spring_layout(H, seed=4)
    fleches = {"arrows": True, "arrowsize": 8} if G.is_directed() else {"arrows": False}
    nx.draw_networkx_edges(H, pos, ax=ax, alpha=0.25, edge_color="#64748b", **fleches)
    noeuds = nx.draw_networkx_nodes(H, pos, ax=ax, cmap="viridis",
                                    node_color=[deg[x] for x in H],
                                    node_size=[250 + 4000 * inter[x] for x in H])
    cibles = list(H) if len(H) <= 60 else sorted(H, key=lambda x: inter[x] + deg[x], reverse=True)[:25]
    noms = {x: prenom_de(G, x) for x in cibles}
    groupes_noms = {}
    for x, t in noms.items():
        groupes_noms.setdefault(t, []).append(x)
    for xs in groupes_noms.values():
        if len(xs) > 1:  # homonymes : nom complet
            for x in xs:
                noms[x] = libelle(G, x)[:18]
    textes = nx.draw_networkx_labels(H, pos, noms, ax=ax, font_weight="bold", font_color="#0f2740",
                                     font_size=9 if len(H) <= 30 else 7)
    for t in textes.values():
        t.set_path_effects([pe.withStroke(linewidth=3, foreground="#eaf6fd")])
    fig.colorbar(noeuds, ax=ax, shrink=0.7, label="Degré (centralité)")
    ax.set_title(titre + " : taille = intermédiarité, couleur = degré")
    ax.axis("off")
    return en_png(fig)


def barres(G, deg, inter):
    fig, axes = plt.subplots(1, 2, figsize=(12, 4.5))
    for ax, data, titre, couleur in ((axes[0], deg, "Degré", "#1a6db0"),
                                     (axes[1], inter, "Intermédiarité", "#e29a00")):
        top = sorted(data, key=data.get, reverse=True)[:10][::-1]
        ax.barh([libelle(G, x)[:28] for x in top], [data[x] for x in top], color=couleur)
        ax.set_title("Top 10 : " + titre)
    fig.tight_layout()
    return en_png(fig)


def entete_nom(G):
    """Intitulé de la colonne selon ce que représentent les nœuds."""
    noeuds = [str(x) for x in G]
    if all(x.startswith("http") for x in noeuds):
        return "Page"
    if all(x.isdigit() for x in noeuds):
        return "Identifiant"
    return "Perso"


def analyser(G):
    n = G.number_of_nodes()
    if G.is_directed():
        deg, brut = nx.in_degree_centrality(G), dict(G.in_degree())
    else:
        deg, brut = nx.degree_centrality(G), dict(G.degree())
    k = 300 if n > 500 else None  # estimation par échantillonnage si le graphe est grand
    inter = nx.betweenness_centrality(G, k=k, seed=1)
    ordre = sorted(G, key=inter.get, reverse=True)
    return {"noeuds": n, "liens": G.number_of_edges(), "approx": k is not None, "entete": entete_nom(G), "resume": G.graph.get("resume", ""),
            "lignes": [(libelle(G, x), brut[x], deg[x], inter[x], str(x)) for x in ordre[:200]],
            "img_graphe": dessiner(G, deg, inter), "img_barres": barres(G, deg, inter)}


