_ICONE = None


def icone():
    """Icône de l'onglet : fichier favicon.png/.jpg/.ico du dossier s'il existe, sinon l'image intégrée (FAVICON_B64)."""
    global _ICONE
    if _ICONE is None:
        for nom in sorted(os.listdir(DOSSIER)):
            if re.fullmatch(r"favicon\.(png|jpe?g|ico|gif|webp)", nom, re.I):
                with open(os.path.join(DOSSIER, nom), "rb") as f:
                    octets = f.read()
                _ICONE = (octets, "image/x-icon" if nom.lower().endswith(".ico") else mime_image(octets))
                break
        else:
            _ICONE = (base64.b64decode(FAVICON_B64), "image/png")
    return _ICONE


@app.route("/favicon.ico")
def favicon():
    octets, mime = icone()
    return Response(octets, mimetype=mime, headers={"Cache-Control": "no-cache"})


@app.route("/", methods=["GET", "POST"])
def accueil():
    ctx = {"url": "", "erreur": None, "res": None}
    if request.method == "POST":
        mode = request.form.get("mode")
        fichiers = [f for f in request.files.getlist("fichiers") if f.filename]
        try:
            if mode == "url":
                url = entree_url(request.form.get("url", ""))
                ctx["url"] = url
                if not url_sure(url):
                    raise ValueError("adresse invalide, locale ou privée : non autorisée")
                G = depuis_site(url, MAX_PAGES)
                if G.number_of_edges() == 0:
                    raise ValueError("aucun lien interne trouvé : le site n'a qu'une page explorable, "
                                     "bloque l'exploration (robots.txt) ou construit ses pages avec JavaScript")
            elif mode == "reseau":
                G = depuis_reseau(request.form.get("reseau", ""), request.form.get("compte", ""),
                                  request.form.get("jeton", "").strip(), "suivis")
            else:  # formulaire « Vos fichiers »
                if not fichiers:
                    raise ValueError("joignez au moins un fichier")
                G = depuis_fichiers(fichiers, bool(request.form.get("oriente")))
            if G.number_of_edges() == 0:
                raise ValueError("aucun lien trouvé")
            ctx["res"] = analyser(G)
        except Exception as e:
            ctx["erreur"] = "Analyse impossible : %s" % (str(e)[:200] or type(e).__name__)
    return render_template_string(PAGE, fond=charger_fond(), groupes=groupes(), **ctx)


